"""Readable phase-4 upper-band diagnostic page for local and public snapshots."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/experiments/20261008-iphone-km184'
data = json.loads((OUT / 'upper-band-residual-qc.json').read_text())
summary = data['summary']
group_names = {'open_notes': '개방현 단음', 'complex': '복합 화음', 'percussion': '퍼커션',
               'strum': '스트로크', 'arpeggio': '아르페지오', 'scale': '스케일',
               'dynamics': '다이내믹', 'slur': '슬러', 'glissando': '글리산도',
               'tremolo': '트레몰로', 'rasgueado': '라스게아도'}
subset = {k: {'windows': v['windows'], 'before': v['group_equal_before_mae_db'],
              'after': v['group_equal_after_mae_db'], 'bands': v['bands'],
              'groups': {g: v['groups'][g] for g in ('open_notes', 'complex', 'percussion', 'strum') if g in v['groups']}}
          for k, v in summary.items()}
payload = json.dumps(subset, ensure_ascii=False, separators=(',', ':'))
names = json.dumps(group_names, ensure_ascii=False)
html = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>10월 네 기기 중고역 잔차 · KM184 기준</title>
<style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#182d37;background:#f5f8f9}body{margin:0}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:clamp(1.65rem,3vw,2.4rem);margin:.5rem 0}h2{font-size:1.35rem;margin-top:2rem}p{line-height:1.6}a{color:#087e8b}nav{display:flex;gap:15px;flex-wrap:wrap}.lead{background:#eaf5f4;border-left:5px solid #087e8b;padding:14px 18px;border-radius:6px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{background:white;border:1px solid #d5dfe3;border-radius:10px;padding:16px}.card strong{font-size:1.25rem}.card span{color:#526773}button{font:inherit;cursor:pointer;border:1px solid #bfd0d2;background:#fff;color:#24424c;border-radius:8px;padding:10px 14px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.controls button[aria-pressed=true]{background:#087e8b;color:white}.chart{background:#fff;border:1px solid #d5dfe3;border-radius:12px;padding:12px;overflow:auto}svg{width:100%;min-width:650px;height:auto}.table-wrap{overflow:auto;background:#fff;border:1px solid #d5dfe3;border-radius:10px}table{border-collapse:collapse;width:100%;min-width:680px}th,td{padding:11px;text-align:left;border-bottom:1px solid #e1e8eb}th{background:#eaf1f3}.note{color:#536b75;font-size:.93rem}.metric{white-space:nowrap}.positive{color:#086a74}.negative{color:#af4927}@media(max-width:740px){.grid{grid-template-columns:repeat(2,1fr)}main{padding:16px}}
</style><main><nav><a href="index.html">10월 비교 홈</a><a href="october-four-device-eq.html#browser">네 기기 같은 시각 재생</a><a href="october-final-filter.html">iPhone 필터 상세</a></nav>
<h1>네 기기의 중고역 잔차</h1><p class="lead">저역 보정은 유지한 채, 현행 필터 뒤에 남는 800Hz–4kHz 차이를 같은 10월 녹음의 유효 5초 창에서 다시 집계했습니다. <b>iPhone의 1.27–1.6kHz 부족과 S21의 약 1.43kHz 부족은 여러 주법에서 반복됩니다.</b> D10·H1은 그 대역의 잔차가 상대적으로 작습니다. 상위 대역을 더 세밀하게 다룰 근거는 있지만, 한 화음의 배음 봉우리마다 좁은 EQ를 붙일 근거는 아닙니다.</p>
<div class="grid" id="cards"></div>
<h2>보정 뒤 남은 대역별 차이</h2><p>세로축은 <b>KM184−기기</b>의 dB입니다. 0보다 높으면 기기 녹음이 부족하고, 낮으면 기기 녹음이 더 큽니다. 선은 보정 후 중앙값, 옅은 범위는 창별 10–90백분위입니다. 버튼을 눌러 기기를 바꿔 보세요.</p><div class="controls" id="devices"></div><div class="chart"><svg id="plot" viewBox="0 0 920 390" role="img" aria-label="기기별 보정 후 주파수 잔차"></svg></div><p id="band-detail" class="note"></p>
<h2>말씀하신 주법의 중고역 오차</h2><p>아래 수치는 관측 가능한 1/6옥타브 대역에서 계산한 절대 오차 평균입니다. 음질 점수가 아니며, 5초 평균이라 어택·감쇠와 개별 배음을 분리하지 않습니다. 퍼커션·스트로크는 창이 적어 방향을 확정하지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>주법</th><th>기기</th><th>유효 창</th><th>원본 → 보정 후</th><th>감소</th></tr></thead><tbody id="group-table"></tbody></table></div>
<h2>이 결과로 결정할 수 있는 것</h2><p><b>iPhone:</b> 1.27·1.43·1.6kHz는 각 11개 주법의 중앙 잔차가 모두 부족 방향입니다. 반면 약 2.0·2.54kHz는 대체로 과다 방향입니다. 한 번에 고역 전체를 키우면 반대 방향 대역을 악화시킬 수 있으므로, 다음 후보는 <b>넓고 완만한 상대 모양 변화</b>로 제한해야 합니다.</p><p><b>S21:</b> 약 1.43kHz는 11개 주법 모두 부족 방향이지만, 1.27kHz는 방향이 반반입니다. 약 3.6kHz 과다는 관측 창이 24개뿐이므로 별도 주의가 필요합니다. <b>D10·H1:</b> 같은 범위의 중앙 잔차가 대체로 작아 현재 필터를 기준으로 유지하는 편이 타당합니다.</p><p class="note">방법: 기존 클리핑·범위·기준 대역 조건을 통과한 창을 사용했습니다. 양쪽에서 기준 대비 −30dB보다 작은 대역은 제외했고, 원본·보정 후에 같은 마스크와 레벨 기준을 썼습니다. 기기별 창 집합과 관측 대역 수가 달라 절대값만으로 마이크 품질 순위를 매길 수 없습니다. S21·D10·H1은 10월 전체 자료로 만든 고정 필터를 이 진단에 적용했으므로 독립 검증이 아닙니다. <a href="upper-band-residual-qc.json">수치 원자료</a>.</p>
</main><script>const data=__DATA__,names=__NAMES__;const colors={iphone:'#087e8b',s21:'#d86135',d10:'#5657a9',h1:'#538f42'};let active='iphone';function fmt(n){return Number(n).toFixed(2)}function build(){document.getElementById('cards').innerHTML=Object.entries(data).map(([k,v])=>`<div class="card"><strong style="color:${colors[k]}">${k.toUpperCase()}</strong><br><span>${v.windows}개 5초 창 · 800Hz–4kHz</span><p>${fmt(v.before)} → <b>${fmt(v.after)}dB</b></p></div>`).join('');document.getElementById('devices').innerHTML=Object.keys(data).map(k=>`<button type="button" data-device="${k}" aria-pressed="${k===active}">${k.toUpperCase()}</button>`).join('');document.querySelectorAll('#devices button').forEach(b=>b.onclick=()=>{active=b.dataset.device;document.querySelectorAll('#devices button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));plot();table()});plot();table()}function plot(){const svg=document.getElementById('plot'),d=data[active].bands,lo=800,hi=4100,x=f=>65+(Math.log(f/lo)/Math.log(hi/lo))*810,y=v=>190-v*13.5;let s='<rect x="0" y="0" width="920" height="390" fill="white"/>';for(const v of [-10,-5,0,5,10])s+=`<line x1="65" y1="${y(v)}" x2="875" y2="${y(v)}" stroke="${v===0?'#4f636c':'#e0e8ea'}"/><text x="10" y="${y(v)+4}" font-size="14" fill="#526773">${v>0?'+':''}${v}</text>`;for(const f of [800,1000,1250,1600,2000,2500,3200,4000])s+=`<text x="${x(f)}" y="360" text-anchor="middle" font-size="13" fill="#526773">${f>=1000?(f/1000)+'k':f}</text>`;const area=d.map((b,i)=>`${i?'L':'M'}${x(b.center_hz)},${y(b.after_q90_db)}`).join(' ')+d.slice().reverse().map(b=>` L${x(b.center_hz)},${y(b.after_q10_db)}`).join(' ')+' Z';s+=`<path d="${area}" fill="${colors[active]}" opacity=".13"/>`;s+=`<polyline points="${d.map(b=>x(b.center_hz)+','+y(b.after_median_db)).join(' ')}" fill="none" stroke="${colors[active]}" stroke-width="3"/>`;for(const b of d)s+=`<circle cx="${x(b.center_hz)}" cy="${y(b.after_median_db)}" r="4" fill="${colors[active]}"><title>${b.center_hz}Hz: ${b.after_median_db>0?'+':''}${b.after_median_db}dB, ${b.windows}창</title></circle>`;svg.innerHTML=s;document.getElementById('band-detail').textContent=active.toUpperCase()+' · 고주파로 갈수록 유효 창이 줄어듭니다. 약 4kHz는 '+d.at(-1).windows+'창에서만 관측됐습니다.'}function table(){let html='';for(const g of ['open_notes','complex','percussion','strum'])for(const k of Object.keys(data)){const v=data[k].groups[g];if(v)html+=`<tr><td>${names[g]}</td><td style="color:${colors[k]}">${k.toUpperCase()}</td><td>${v.windows}</td><td class="metric">${fmt(v.before_mae_db)} → ${fmt(v.after_mae_db)}dB</td><td class="metric ${v.before_mae_db-v.after_mae_db>=0?'positive':'negative'}">${(v.before_mae_db-v.after_mae_db>=0?'+':'')+fmt(v.before_mae_db-v.after_mae_db)}dB</td></tr>`}document.getElementById('group-table').innerHTML=html}build()</script></html>'''
html = html.replace('__DATA__', payload).replace('__NAMES__', names)
(OUT / 'upper-band-residual-qc.html').write_text(html)
print(OUT / 'upper-band-residual-qc.html')
